// Turbofan showpiece, hand-made. Units: cm. The engine's axis is X (the fan faces +X), its centre line at y = 120 on a
// maintenance stand. Shared helpers for every later part live on W.store.
const S = W.store;
const deg = (d) => d * Math.PI / 180;
S.Y = 120;
S.axisLathe = (profile, seg = 96, phiStart = 0, phiLen = Math.PI * 2) => { // a lathe around the X axis: [r, x] points
  const g = new THREE.LatheGeometry(profile.map((p) => new THREE.Vector2(Math.max(0.001, p[0]), p[1])), seg, phiStart, phiLen);
  g.rotateZ(-Math.PI / 2);
  return g;
};
S.blade = (o) => { // one aerofoil blade: span along +Y from y = 0, chord along X, twisted about its span
  const ns = o.ns || 10, nc = o.nc || 8, span = o.span, c0 = o.root, c1 = o.tip == null ? o.root : o.tip;
  const tw = deg(o.twist || 0), p0 = deg(o.pitch || 0), th = o.thick || 0.06, cam = o.camber == null ? 0.07 : o.camber;
  const pos = [], idx = [], col = [], ring = nc * 2;
  const c3 = new THREE.Color();
  for (let i = 0; i <= ns; i++) {
    const s = i / ns, c = c0 + (c1 - c0) * Math.pow(s, 0.85), a = p0 + tw * s;
    const x0 = (o.sweep || 0) * Math.pow(s, 1.5), z0 = (o.lean || 0) * s, y = span * s, ca = Math.cos(a), sa = Math.sin(a);
    if (o.colors) { const k = o.colors(s); c3.set(k); }
    for (let side = 0; side < 2; side++) {
      for (let j = 0; j < nc; j++) {
        const u = side === 0 ? j / (nc - 1) : 1 - j / (nc - 1);
        const t = 5 * th * (0.2969 * Math.sqrt(u) - 0.126 * u - 0.3516 * u * u + 0.2843 * u * u * u - 0.1036 * u * u * u * u);
        const zc = cam * 4 * u * (1 - u), x = (u - 0.4) * c, z = (zc + (side === 0 ? t : -t)) * c;
        pos.push(x0 + x * ca - z * sa, y, z0 + x * sa + z * ca);
        if (o.colors) col.push(c3.r, c3.g, c3.b);
      }
    }
  }
  for (let i = 0; i < ns; i++) for (let j = 0; j < ring; j++) {
    const a = i * ring + j, b = i * ring + (j + 1) % ring, c = (i + 1) * ring + j, d = (i + 1) * ring + (j + 1) % ring;
    idx.push(a, c, b, b, c, d);
  }
  const tip = ns * ring;
  for (let j = 1; j < ring - 1; j++) idx.push(tip, tip + j, tip + j + 1);
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  if (o.colors) g.setAttribute('color', new THREE.Float32BufferAttribute(col, 3));
  g.setIndex(idx);
  g.computeVertexNormals();
  return g;
};
S.ring = (geo, mat, n, r, x, o = {}) => { // n copies around the X axis, roots at radius r, at axial station x
  const m = new THREE.InstancedMesh(geo, mat, n);
  const M = new THREE.Matrix4(), R = new THREE.Matrix4(), T = new THREE.Matrix4();
  for (let i = 0; i < n; i++) {
    const a = (i / n) * Math.PI * 2 + (o.phase || 0);
    R.makeRotationX(a);
    T.makeTranslation(x, r, 0);
    M.multiplyMatrices(R, T);
    m.setMatrixAt(i, M);
  }
  m.castShadow = true;
  m.receiveShadow = true;
  return m;
};
S.bolts = (n, r, x, size, mat) => { // a row of bolt heads around the axis
  const g = new THREE.CylinderGeometry(size, size, size * 0.9, 6);
  return S.ring(g, mat, n, r, x);
};
S.mTi = W.metal('#a7acb3', { rough: 0.24 });
S.mSteel = W.metal('brushed', { rough: 0.38 });
S.mDark = W.metal('#5d636b', { rough: 0.42 });
S.mNickel = W.metal('#9b958c', { rough: 0.33 });
S.mBolt = W.metal('#c9cdd2', { rough: 0.3 });
S.heatTint = (s) => (s < 0.3 ? '#c9a46a' : s < 0.65 ? '#6f6fa8' : '#8a6a4a'); // straw at the root, blue, bronze at the tip
S.hot = []; // (materials that glow with the power)
S.lp = []; // the low-pressure spool: the fan, the booster, its turbine (turn slower)
S.hp = []; // the high-pressure spool (turns fast)

// the stand: welded box-section steel, two cradles, feet on castors
const paint = W.paint('#2a2f36', { metallic: 0.5, rough: 0.5 });
const st = W.group();
const tube = (len, along, x, y, z) => {
  const g = along === 'x' ? W.box(len, 8, 8, 0.6) : along === 'y' ? W.box(8, len, 8, 0.6) : W.box(8, 8, len, 0.6);
  st.add(W.mesh(g, paint, { at: [x, y, z] }));
};
tube(300, 'x', -15, 14, 62); tube(300, 'x', -15, 14, -62);
for (const x of [-150, -60, 40, 120]) tube(124, 'z', x, 14, 0);
for (const [x, r] of [[40, 40.5], [-60, 46.5]]) { // the cradles: a saddle that holds the casing, on two posts
  const top = S.Y - r - 4;
  for (const z of [-46, 46]) tube(top - 18, 'y', x, 18 + (top - 18) / 2, z);
  tube(100, 'z', x, top, 0);
  const saddle = new THREE.Mesh(new THREE.TorusGeometry(r + 1.8, 3.4, 10, 40, Math.PI * 0.62), paint);
  saddle.rotation.set(0, Math.PI / 2, Math.PI + Math.PI * 0.19);
  saddle.position.set(x, S.Y, 0);
  st.add(saddle);
  for (const z of [-1, 1]) st.add(W.mesh(W.box(8, top - S.Y + r + 6, 5, 1), paint, { at: [x, (top + S.Y - r + 2) / 2, z * r * 0.62] }));
}
for (const x of [-160, 130]) for (const z of [-62, 62]) { // castors
  st.add(W.mesh(W.box(12, 4, 12, 1), S.mDark, { at: [x, 8, z] }));
  st.add(W.mesh(W.cyl(5, 5, 4, 24), W.rubber(), { at: [x, 5, z], rot: [90, 0, 0] }));
}
st.add(W.text('JARVIS WORKSHOP · ENGINE STAND', { size: 2.2, at: [-15, 14, 66.2], color: '#d9dde3' }));
W.add(st, { label: 'స్టాండ్' });

const S = W.store;
const lpShaft = W.group();
lpShaft.add(W.mesh(W.cyl(5.5, 5.5, 262, 40), W.metal('#b8bcc2', { rough: 0.28 }), { at: [-12, S.Y, 0], rot: [0, 0, 90] }));
for (const x of [-120, -60, 40, 100]) lpShaft.add(W.mesh(W.cyl(7, 7, 3, 32), S.mDark, { at: [x, S.Y, 0], rot: [0, 0, 90] }));
W.add(lpShaft, { label: 'లో-ప్రెషర్ షాఫ్ట్', heat: [40, 120] });
S.lp.push(lpShaft.children[0]);
const hpShaft = W.group();
hpShaft.add(W.mesh(S.axisLathe([[9.5, -48], [10.5, -48], [10.5, 52], [9.5, 52], [9.5, -48]], 48), W.metal('#c4b28e', { rough: 0.3 })));
hpShaft.children[0].position.y = S.Y;
W.add(hpShaft, { label: 'హై-ప్రెషర్ షాఫ్ట్', heat: [60, 260] });

const S = W.store;
const fc = W.group();
// the case: polished lip at the front, a composite band, fastener rings, guide vanes behind the fan
const shell = S.axisLathe([[78, 70], [78, 124], [79.5, 128.5], [82.5, 130], [86, 128], [86.5, 120], [85.5, 72], [84, 70], [78, 70]], 120);
const caseMat = W.metal('#b9bec5', { rough: 0.3 });
const sh = new THREE.Mesh(shell, caseMat);
sh.position.y = S.Y;
fc.add(sh);
const lip = new THREE.Mesh(new THREE.TorusGeometry(81.5, 3.2, 16, 120), W.metal('chrome', { rough: 0.08 }));
lip.rotation.y = Math.PI / 2;
lip.position.set(127.5, S.Y, 0);
fc.add(lip);
const weave = W.canvasTex(256, 256);
{
  const g = weave.ctx;
  g.fillStyle = '#1b1d21'; g.fillRect(0, 0, 256, 256);
  for (let y = 0; y < 256; y += 16) for (let x = 0; x < 256; x += 16) {
    const odd = ((x + y) / 16) % 2;
    const gr = g.createLinearGradient(x, y, x + 16, y + 16);
    gr.addColorStop(0, odd ? '#2c3036' : '#24272c'); gr.addColorStop(1, odd ? '#15171a' : '#30343a');
    g.fillStyle = gr; g.fillRect(x + 1, y + 1, 14, 14);
  }
  weave.update();
  weave.texture.wrapS = weave.texture.wrapT = THREE.RepeatWrapping;
  weave.texture.repeat.set(40, 3);
}
const band = new THREE.Mesh(S.axisLathe([[86.8, 82], [86.8, 116]], 120), new THREE.MeshPhysicalMaterial({ map: weave.texture, roughness: 0.38,
  metalness: 0.25, clearcoat: 0.8, clearcoatRoughness: 0.2, side: THREE.DoubleSide }));
band.position.y = S.Y;
fc.add(band);
for (const x of [74, 121]) { const b = S.bolts(64, 86.6, x, 0.9, S.mBolt); b.position.y = S.Y; b.rotation.z = 0; fc.add(b); }
// guide vanes (outlet guide vanes): still, they straighten the fan's air
const ogv = S.blade({ span: 33, root: 9, tip: 10, twist: 6, pitch: 8, thick: 0.08, camber: 0.05, ns: 4, nc: 6 });
const vanes = S.ring(ogv, W.metal('#8f949b', { rough: 0.35 }), 40, 45.5, 76);
vanes.position.y = S.Y;
fc.add(vanes);
const plate = W.group({ at: [100, S.Y + 54, 66], rot: [0, 0, 0] });
plate.add(W.mesh(W.box(30, 7, 0.6, 0.3), W.metal('#d8dade', { rough: 0.2 })));
plate.add(W.text('TURBOFAN · JARVIS WORKSHOP', { size: 1.6, at: [0, 0, 0.4], color: '#2a2f36' }));
plate.lookAt(new THREE.Vector3(100, S.Y + 54 + 54, 66 + 66));
fc.add(plate);
W.add(fc, { label: 'ఫ్యాన్ కేస్', explode: [110, 0, 0], heat: [25, 34], layer: 0 });

const S = W.store;
// 22 wide-chord, swept titanium blades with real twist, on a disc; the spinner with its painted spiral in front
const fan = W.group();
const rotor = W.group({ at: [106, S.Y, 0] });
const bl = S.blade({ span: 54, root: 17, tip: 31, twist: 34, pitch: 28, thick: 0.045, camber: 0.07, sweep: -7, lean: 3, ns: 16, nc: 12 });
const blades = S.ring(bl, W.metal('#b4b9bf', { rough: 0.2 }), 22, 21.5, 0);
rotor.add(blades);
rotor.add(W.mesh(S.axisLathe([[10, -14], [23, -14], [23.5, -10], [23.5, 10], [21, 13], [10, 13]], 64), S.mTi));
fan.add(rotor);
S.lp.push(rotor);
S.fanRotor = rotor;
W.add(fan, { label: 'ఫ్యాన్ బ్లేడ్లు', explode: [165, 0, 0], heat: [24, 32], layer: 1 });
// the spinner: an ogive cone, a white spiral painted on it (it tells the ground crew the fan is turning)
const spin = W.group();
const tex = W.canvasTex(512, 512);
{
  const g = tex.ctx;
  g.fillStyle = '#1d2024'; g.fillRect(0, 0, 512, 512);
  g.strokeStyle = '#f4f6f8'; g.lineWidth = 34; g.lineCap = 'round';
  g.beginPath(); g.moveTo(0, 512); g.lineTo(512, 40); g.stroke();
  tex.update();
}
const prof = [];
for (let i = 0; i <= 16; i++) { const s = i / 16; prof.push([22 * Math.sqrt(1 - s * s * 0.98) * (1 - s * 0.15), s * 38]); }
prof.push([0.01, 38]);
const cone = new THREE.Mesh(S.axisLathe(prof, 64), new THREE.MeshPhysicalMaterial({ map: tex.texture, metalness: 0.35, roughness: 0.25, clearcoat: 1 }));
cone.position.set(119, S.Y, 0);
spin.add(cone);
W.add(spin, { label: 'స్పిన్నర్', explode: [212, 0, 0], layer: 1 });
S.lp.push(cone);

const S = W.store;
const bo = W.group();
const rot = W.group({ at: [0, S.Y, 0] });
const still = W.group({ at: [0, S.Y, 0] });
rot.add(W.mesh(S.axisLathe([[22, 58], [27, 60], [26, 90], [21, 93], [22, 58]], 64), S.mTi));
const stage = (x, n, hub, tip, chord) => {
  rot.add(S.ring(S.blade({ span: tip - hub, root: chord, tip: chord * 0.9, twist: 22, pitch: 38, thick: 0.07, ns: 5, nc: 6 }), S.mTi, n, hub, x));
};
stage(86, 46, 26, 41, 5); stage(77, 50, 25.5, 39.5, 4.6); stage(68, 54, 25, 38, 4.2);
for (const x of [81.5, 72.5, 63.5]) still.add(S.ring(S.blade({ span: 14, root: 3.6, twist: 4, pitch: -24, thick: 0.08, ns: 3, nc: 5 }), S.mDark, 60, 26, x));
bo.add(rot, still);
S.lp.push(rot);
W.add(bo, { label: 'లో-ప్రెషర్ కంప్రెసర్', explode: [68, 0, 0], heat: [30, 95], layer: 2 });

const S = W.store;
// nine stages: the drum widens, the blades get shorter toward the back, so the air is squeezed into a smaller ring
const hpc = W.group();
const rot = W.group({ at: [0, S.Y, 0] });
const still = W.group({ at: [0, S.Y, 0] });
rot.add(W.mesh(S.axisLathe([[18, 2], [23, 4], [19, 50], [14, 52], [18, 2]], 64), W.metal('#b7b2a6', { rough: 0.28 })));
for (let i = 0; i < 9; i++) {
  const k = i / 8, x = 47 - i * 5.3, hub = 19 + k * 3.6, tip = 31 - k * 4.4, n = Math.round(38 + k * 30);
  rot.add(S.ring(S.blade({ span: tip - hub, root: 3.4 - k * 1.3, tip: 3.0 - k * 1.1, twist: 14, pitch: 42, thick: 0.08, ns: 3, nc: 5 }),
    W.metal(k < 0.5 ? '#b9bcc0' : '#b6a98f', { rough: 0.27 }), n, hub, x));
  if (i < 8) still.add(S.ring(S.blade({ span: tip - hub - 0.6, root: 2.4 - k * 0.8, twist: 3, pitch: -30, thick: 0.09, ns: 2, nc: 5 }), S.mDark, n + 6, hub + 0.3, x - 2.65));
}
hpc.add(rot, still);
S.hp.push(rot);
W.add(hpc, { label: 'హై-ప్రెషర్ కంప్రెసర్', heat: [70, 560], layer: 3 });

const S = W.store;
// an annular liner with rows of dilution holes and a ring of fuel nozzles; the fire inside glows with the power
const cb = W.group();
const liner = new THREE.Mesh(S.axisLathe([[24, -32], [21.5, -20], [22, -4], [25, 0.5], [30, 1.5], [35, 0], [36.5, -6], [35.5, -20], [33, -32], [24, -32]], 96),
  W.metal('#a29a8e', { rough: 0.36 }));
liner.position.y = S.Y;
cb.add(liner);
const hole = new THREE.CylinderGeometry(0.85, 0.85, 0.5, 12);
const holeMat = new THREE.MeshStandardMaterial({ color: 0x120c08, emissive: 0xff7a1a, emissiveIntensity: 0 });
S.hot.push({ m: holeMat, k: 2.6 });
for (const [x, r, n] of [[-8, 36.2, 30], [-16, 35.8, 30], [-24, 34.6, 26]]) {
  const h = new THREE.InstancedMesh(hole, holeMat, n);
  const M = new THREE.Matrix4(), R = new THREE.Matrix4(), T = new THREE.Matrix4();
  for (let i = 0; i < n; i++) { R.makeRotationX((i + (x === -16 ? 0.5 : 0)) / n * Math.PI * 2); T.makeTranslation(x, r, 0); M.multiplyMatrices(R, T); h.setMatrixAt(i, M); }
  h.position.y = S.Y;
  cb.add(h);
}
const fire = new THREE.Mesh(S.axisLathe([[26, -30], [24, -6], [27, -1], [33, -1], [34, -6], [32, -30], [26, -30]], 64),
  new THREE.MeshStandardMaterial({ color: 0x220a02, emissive: 0xff8a2a, emissiveIntensity: 0, side: THREE.BackSide }));
fire.position.y = S.Y;
fire.scale.set(0.98, 0.95, 0.95);
cb.add(fire);
S.hot.push({ m: fire.material, k: 3.2 });
// twenty fuel nozzles reach in through the casing to the front of the liner
const nz = new THREE.Group();
const stem = W.cyl(1.2, 1.2, 12, 12), head = W.sphere(1.9, 14);
const nzMat = W.metal('#c8b98f', { rough: 0.3 });
for (let i = 0; i < 20; i++) {
  const a = (i / 20) * Math.PI * 2, g = new THREE.Group();
  g.add(W.mesh(stem, nzMat, { at: [0, 41, 0] }));
  g.add(W.mesh(head, nzMat, { at: [0, 35.5, 0] }));
  g.add(W.mesh(W.box(3, 2, 3, 0.4), nzMat, { at: [0, 47, 0] }));
  g.position.set(2.5, 0, 0);
  g.rotation.x = a;
  nz.add(g);
}
nz.position.y = S.Y;
cb.add(nz);
W.add(cb, { label: 'దహన గది', explode: [-30, 0, 0], heat: [520, 1450], layer: 3 });

const S = W.store;
const ht = W.group();
const rot = W.group({ at: [0, S.Y, 0] });
const still = W.group({ at: [0, S.Y, 0] });
const tint = S.blade({ span: 9.5, root: 3.6, tip: 3.3, twist: 18, pitch: -48, thick: 0.14, camber: 0.14, ns: 5, nc: 6, colors: S.heatTint });
const tMat = new THREE.MeshPhysicalMaterial({ vertexColors: true, metalness: 1, roughness: 0.3, emissive: 0xff3c10, emissiveIntensity: 0 });
S.hot.push({ m: tMat, k: 0.5 });
rot.add(S.ring(tint, tMat, 72, 24.5, -41));
rot.add(W.mesh(S.axisLathe([[8, -44], [24.8, -44], [24.8, -38], [8, -38]], 64), W.metal('#8d8478', { rough: 0.35 })));
still.add(S.ring(S.blade({ span: 9.6, root: 4, twist: 6, pitch: 52, thick: 0.18, camber: 0.18, ns: 3, nc: 6, colors: S.heatTint }), tMat, 40, 24.4, -35));
ht.add(rot, still);
S.hp.push(rot);
W.add(ht, { label: 'హై-ప్రెషర్ టర్బైన్', explode: [-62, 0, 0], heat: [480, 1050], layer: 3 });

const S = W.store;
const lt = W.group();
const rot = W.group({ at: [0, S.Y, 0] });
const still = W.group({ at: [0, S.Y, 0] });
const lMat = new THREE.MeshPhysicalMaterial({ vertexColors: true, metalness: 1, roughness: 0.32, emissive: 0xff4a14, emissiveIntensity: 0 });
S.hot.push({ m: lMat, k: 0.35 });
for (let i = 0; i < 4; i++) {
  const k = i / 3, x = -52 - i * 12, hub = 24.5 + k * 4, tip = 35 + k * 9;
  rot.add(S.ring(S.blade({ span: tip - hub, root: 3.4 + k * 0.6, tip: 3.0 + k * 0.5, twist: 26, pitch: -50, thick: 0.11, camber: 0.12, ns: 5, nc: 6,
    colors: (s) => (s < 0.5 ? '#9a7a55' : '#7b6a8e') }), lMat, 84 + i * 8, hub, x));
  rot.add(W.mesh(S.axisLathe([[9, x - 2], [hub + 0.3, x - 2], [hub + 0.3, x + 2], [9, x + 2]], 64), W.metal('#8a8176', { rough: 0.35 })));
  still.add(S.ring(S.blade({ span: tip - hub - 0.6, root: 3.4, twist: 5, pitch: 46, thick: 0.13, camber: 0.14, ns: 3, nc: 5 }), S.mNickel, 70 + i * 6, hub + 0.3, x + 6));
}
lt.add(rot, still);
S.lp.push(rot);
W.add(lt, { label: 'లో-ప్రెషర్ టర్బైన్', explode: [-102, 0, 0], heat: [380, 760], layer: 3 });

const S = W.store;
const ex = W.group();
const noz = new THREE.Mesh(S.axisLathe([[47.5, -98], [44, -128], [41.5, -136], [43.5, -136], [46.5, -128], [50.5, -98], [47.5, -98]], 120),
  W.metal('#a8a29a', { rough: 0.3 }));
noz.position.y = S.Y;
ex.add(noz);
const inner = new THREE.Mesh(S.axisLathe([[47.2, -98.5], [43.7, -128], [41.6, -135.5]], 120),
  new THREE.MeshStandardMaterial({ color: 0x2a1a12, metalness: 0.6, roughness: 0.5, emissive: 0xff5a1a, emissiveIntensity: 0, side: THREE.BackSide }));
inner.position.y = S.Y;
ex.add(inner);
S.hot.push({ m: inner.material, k: 0.9 });
const b = S.bolts(60, 51, -100, 0.8, S.mBolt); b.position.y = S.Y; ex.add(b);
W.add(ex, { label: 'ఎగ్జాస్ట్ నాజిల్', explode: [-145, 0, 0], heat: [280, 640], layer: 0 });
const plug = W.group();
const prof = [];
for (let i = 0; i <= 14; i++) { const s = i / 14; prof.push([24 * (1 - Math.pow(s, 1.6)) + 0.01, -98 - s * 58]); }
const pm = new THREE.MeshPhysicalMaterial({ color: 0x5b5651, metalness: 1, roughness: 0.34, emissive: 0xff5a1a, emissiveIntensity: 0 });
const pl = new THREE.Mesh(S.axisLathe(prof, 64), pm);
pl.position.y = S.Y;
plug.add(pl);
S.hot.push({ m: pm, k: 0.45 });
W.add(plug, { label: 'ఎగ్జాస్ట్ కోన్', explode: [-190, 0, 0], heat: [300, 620], layer: 0 });

const S = W.store;
// the core's casing, split along its length: the upper half lifts away when the engine opens, the lower half stays
const prof = [[45, 70], [44, 58], [39, 50], [36, 30], [36, 4], [41, -2], [42, -34], [40, -44], [42, -52], [49, -96], [49, -98]];
const outer = prof.map(([r, x]) => [r + 1.6, x]).reverse();
const shape = prof.concat(outer, [prof[0]]);
const cMat = W.metal('#9fa5ac', { rough: 0.36 });
const half = (up) => {
  const g = W.group();
  const m = new THREE.Mesh(S.axisLathe(shape, 64, up ? Math.PI : 0, Math.PI), cMat);
  m.position.y = S.Y;
